<script setup lang="ts">
const creationRequestId=ref(crypto.randomUUID())
import {compareRequirements} from '#shared/utils/analysis'
import {money} from '#shared/utils/pricing'
const db=useDb(),w=useWorkspace(),route=useRoute(),{error,busy,notice,run}=useAction(),lines=ref<any[]>([]),candidates=ref<Record<string,any[]>>({}),queries=ref<Record<string,string>>({}),comparison=ref<any|null>(null),mode=ref('deterministic')
const {data:enquiry,refresh}=await useAsyncData('enquiry-'+route.params.id,async()=>{const e=check(await db.from('quolyn_enquiries').select('*,quolyn_customers(name)').eq('workspace_id',w.value!.id).eq('id',route.params.id).single());lines.value=check(await db.from('quolyn_enquiry_lines').select('*,quolyn_products(name,sku)').eq('enquiry_id',e.id).order('position'));return e})
async function saveDelivery(){await run(async()=>{check(await db.from('quolyn_enquiries').update({delivery_date:enquiry.value!.delivery_date||null,notes:enquiry.value!.notes}).eq('id',enquiry.value!.id));notice.value='Enquiry delivery details saved'})}
function checks(l:any,p:any){return compareRequirements({...l.requirements,...(l.brand?{brand:l.brand}:{})},{...p.attributes,brand:p.brand||null})}
const confirmed=computed(()=>lines.value.filter(l=>['confirmed','excluded'].includes(l.state)).length)
async function analyse(){await run(async()=>{const reviewed=lines.value.some(l=>l.state==='confirmed'||l.corrections>0);if(lines.value.length&&!window.confirm('Reanalysis replaces existing interpretation and review work. Continue?'))return;const r=await db.functions.invoke('analyse-enquiry',{body:{workspace_id:w.value!.id,enquiry_id:enquiry.value!.id,mode:mode.value,replace_reviewed:reviewed}});if(r.error){let msg=r.error.message;try{msg=(await r.error.context.json()).error||msg}catch{}throw new Error(msg)}if(r.data.error)throw new Error(r.data.error);await refresh();notice.value='Analysis saved. Review every quantity, specification and delivery requirement.'})}
async function save(l:any){await run(async()=>{const {quolyn_products,...row}=l;row.quantity=row.quantity||null;row.corrections=(row.corrections||0)+1;check(await db.from('quolyn_enquiry_lines').upsert(row));await refresh();notice.value='Review saved'})}
async function find(l:any){await run(async()=>{const found=check(await db.rpc('suggest_products',{w:w.value!.id,l:l.id,q:queries.value[l.id]||l.sku||l.description}))||[];const reasons=check(await db.from('quolyn_match_candidates').select('product_id,reasons,strength').eq('line_id',l.id));candidates.value[l.id]=found.map((p:any)=>({...p,match_info:reasons.find(r=>r.product_id===p.id)}))})}
function choose(l:any,p:any){l.product_id=p.id;l.quolyn_products={name:p.name,sku:p.sku};l.state='suggested';candidates.value[l.id]=[]}
async function add(source?:any){await run(async()=>{const p={workspace_id:w.value!.id,enquiry_id:enquiry.value!.id,position:lines.value.length+1,description:source?.description||'New requirement',original_text:source?.original_text||'',requirements:source?.requirements||{},missing:['Quantity and requirements need review'],state:'needs clarification'};check(await db.from('quolyn_enquiry_lines').insert(p));await refresh()})}
async function remove(l:any){await run(async()=>{if(!window.confirm('Remove this interpretation line? The original enquiry is preserved.'))return;check(await db.from('quolyn_enquiry_lines').delete().eq('id',l.id));await refresh()})}
async function combine(l:any){await run(async()=>{const other=lines.value.find(x=>x.id!==l.id&&x.description===l.description&&x.unit===l.unit);if(!other)throw new Error('No duplicate with the same description and unit. Save matching fields first.');check(await db.rpc('combine_lines',{w:w.value!.id,target_id:l.id,source_id:other.id}));await refresh()})}
async function quote(){await run(async()=>{const rows=lines.value.filter(l=>l.state!=='excluded').map(l=>({enquiry_line_id:l.id,product_id:l.product_id,description:l.description,quantity:l.quantity?.toString()||'',unit:l.unit,reviewed:false,requirements_resolved:l.state==='confirmed',included:true}));const q=check(await db.rpc('save_quote',{w:w.value!.id,p:{request_id:creationRequestId.value,customer_id:enquiry.value!.customer_id,enquiry_id:enquiry.value!.id,lines:rows}}));await navigateTo('/quotes/'+q)})}
const unitOptions=await useUnitOptions()
</script>
<template><div v-if="enquiry"><div class="page-title"><div><div class="eyebrow">ENQUIRIES / REVIEW</div><h1>{{enquiry.title}}</h1><p>{{enquiry.quolyn_customers?.name||'Customer not assigned'}} · {{enquiry.source}} · {{enquiry.received_date}}</p></div><span class="pill">{{confirmed}} of {{lines.length}} reviewed</span></div><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert success">{{notice}}</p><div class="split"><aside><div class="original"><span class="eyebrow">ORIGINAL ENQUIRY</span><blockquote>{{enquiry.original_text}}</blockquote><div class="row"><select v-model="mode" aria-label="Analysis mode"><option value="deterministic">Deterministic analysis</option><option value="ai">AI (requires configuration)</option></select><button class="secondary wide" :disabled="busy" @click="analyse">{{lines.length?'Reanalyse enquiry':'Analyse enquiry'}} →</button></div><p class="fine">Deterministic mode identifies explicit quantities and splits text. It cannot establish suitability or compatibility.</p></div><div v-if="enquiry.analysis_notes?.length" class="alert warning"><b>Notes & delivery</b><p v-for="n in enquiry.analysis_notes" :key="n">{{n}}</p></div><div class="panel" style="margin-top:20px"><label>Confirmed delivery date<input v-model="enquiry.delivery_date" type="date"></label><label>Internal enquiry note<textarea v-model="enquiry.notes"></textarea></label><button class="secondary" @click="saveDelivery">Save enquiry details</button></div><div class="panel" style="margin-top:20px"><ActivityLog :entity-id="enquiry.id" /></div></aside><section><div class="row between" style="margin-bottom:15px"><h2>Review requirements</h2><button class="link" @click="add()">＋ Add line</button></div><div v-if="!lines.length" class="panel empty"><div class="empty-icon">≋</div><h3>Turn the request into editable lines</h3><p>Analyse the enquiry, or add requirements manually.</p><button class="primary" :disabled="busy" @click="analyse">Analyse enquiry</button></div><article v-for="(l,i) in lines" :key="l.id" class="line-card"><div class="line-header"><span class="line-number">LINE {{String(i+1).padStart(2,'0')}}</span><span class="pill" :class="l.state">{{l.state}}</span></div><div class="line-fields"><label>Requested product<input v-model="l.description"></label><label>Quantity<input v-model="l.quantity" type="number" min="0.000001" step="any" placeholder="Unknown"></label><label>Unit<select v-model="l.unit"><option :value="null">Unknown</option><option v-for="u in unitOptions" :key="u">{{u}}</option></select></label></div><div class="form-grid"><label>SKU<input v-model="l.sku"></label><label>Brand<input v-model="l.brand"></label></div><label>Required specifications (one key: value per line)<textarea :value="Object.entries(l.requirements).map(([k,v])=>`${k}: ${v}`).join('\n')" @change="l.requirements=Object.fromEntries(($event.target as HTMLTextAreaElement).value.split('\n').filter(s=>s.includes(':')).map(s=>s.split(/:(.*)/s).slice(0,2).map(x=>x.trim())))" style="min-height:55px"></textarea></label><div v-if="l.missing.length" class="alert warning"><b>Needs clarification</b><label v-for="(m,j) in l.missing" :key="m"><input type="checkbox" @change="l.missing.splice(j,1)">Resolved: {{m}}</label></div><label>Clarification / customer answer<input v-model="l.clarification" placeholder="Record the answer before confirming"></label><div v-if="l.product_id" class="alert success"><b>Selected:</b> {{l.quolyn_products?.name||l.product_id}}<small> · {{l.quolyn_products?.sku}}</small></div><div class="row"><input v-model="queries[l.id]" :placeholder="l.sku||'Search by SKU, alias or product words'" :aria-label="'Product search line '+(i+1)" style="flex:1;margin:0"><button class="secondary" :disabled="busy" @click="find(l)">Find products</button></div><div v-if="candidates[l.id]?.length===0" class="muted" style="font-size:11px;margin-top:10px">No candidates shown. Search again or use a manual item.</div><div v-for="p in candidates[l.id]" :key="p.id" class="candidate"><div class="row between"><b>{{p.name}}</b><span>{{money(p.price_minor,p.currency)}} / {{p.price_unit}}</span></div><p>{{p.sku||'No SKU'}} · {{p.stock_status}} · updated {{new Date(p.updated_at).toLocaleDateString()}}</p><span class="pill" :class="checks(l,p).conflicts.length?'rejected':'neutral'">{{checks(l,p).conflicts.length?'Specification conflict':p.match_info?.strength||'Possible match'}}</span><p>{{p.match_info?.reasons?.join('; ')}}</p><p v-if="checks(l,p).unknown.length">{{checks(l,p).unknown.length}} required specifications are unknown.</p><div class="row"><button class="link" @click="comparison={product:p,checks:checks(l,p)}">Compare specifications</button><button class="link" @click="choose(l,p)">Select suggestion →</button></div></div><div class="row" style="margin-top:13px"><label><input v-model="l.manual" type="checkbox">Manual quote item</label><select v-model="l.state" aria-label="Line review state" style="width:auto"><option v-for="s in ['unmatched','needs clarification','suggested','confirmed','excluded']" :key="s">{{s}}</option></select></div><label v-if="l.state==='excluded'">Exclusion reason<input v-model="l.exclusion_reason" required></label><div class="row between"><div class="row"><button class="link" @click="add(l)">Split</button><button class="link" @click="combine(l)">Combine duplicate</button><button class="link" @click="remove(l)">Remove</button></div><button class="secondary mini" :disabled="busy" @click="save(l)">Save line</button></div></article><div class="sticky-actions"><span class="muted">{{lines.length-confirmed}} lines need review</span><button class="primary" :disabled="busy||!lines.length" @click="quote">Create quotation draft →</button></div></section></div><template v-if="comparison"><div class="drawer-backdrop" @click="comparison=null"></div><aside class="drawer"><div class="row between"><h2>{{comparison.product.name}}</h2><button class="secondary mini" @click="comparison=null">Close</button></div><p class="muted">Match labels are heuristics, not probabilities.</p><div v-for="key in ['confirmed','conflicts','unknown']" :key="key" class="panel"><h3>{{key}}</h3><p v-for="v in comparison.checks[key]" :key="v">{{v}}</p><p v-if="!comparison.checks[key].length" class="muted">None recorded</p></div><dl class="detail-grid" style="margin-top:25px"><div v-for="(v,k) in comparison.product.attributes" :key="k"><dt>{{k}}</dt><dd>{{v}}</dd></div></dl></aside></template></div></template>
